      function syncLineToolUI(){const on=!!state.lineTool;btnLineTool.textContent=on?'Line Tool: On':'Line Tool: Off';btnLineTool.classList.toggle('alt',on);btnLineTool.classList.toggle('ghost',!on);btnLineTool.style.background=on?'#e5e7eb':'#fff';btnLineTool.style.color='#111';syncCanvasToolCursor();syncModeHUD?.();}
      btnLineTool.onclick=()=>{state.lineTool=!state.lineTool;if(state.lineTool){state.dimTool=false;state.noteTool=false;syncDimToolUI?.();syncNoteToolUI();}if(!state.lineTool)lineTempStart=null;syncLineToolUI();}; syncLineToolUI();

