      const canvasScrollWrap=canvasCard?.querySelector('.lc-canvas-wrap')||null;
      let zoomWheelCommitTimer=null;
      canvasScrollWrap?.addEventListener('wheel',e=>{
        if(!e.shiftKey||!zoomWheelZHeld||planModalCleanup)return;
        e.preventDefault();
        const rect=canvasScrollWrap.getBoundingClientRect();
        const localX=e.clientX-rect.left;
        const localY=e.clientY-rect.top;
        const oldScale=state.scale;
        const contentX=canvasScrollWrap.scrollLeft+localX;
        const contentY=canvasScrollWrap.scrollTop+localY;
        const worldX=contentX/oldScale;
        const worldY=contentY/oldScale;
        const direction=e.deltaY<0?1:-1;
        const next=clamp(oldScale+direction*.5,zoomMin,zoomMax);
        if(next===oldScale)return;
        setCanvasZoom(next,{save:false,history:false});
        canvasScrollWrap.scrollLeft=Math.max(0,worldX*next-localX);
        canvasScrollWrap.scrollTop=Math.max(0,worldY*next-localY);
        clearTimeout(zoomWheelCommitTimer);
        zoomWheelCommitTimer=setTimeout(()=>{scheduleSave?.();pushHistory?.();},180);
      },{passive:false});
      let layoutWorkspaceTab=null;
