          heightInput.max='24';
          heightInput.step='.25';
          heightInput.setAttribute('aria-label','Splash height in inches');
          heightWrap.append(heightLabel,heightInput);

          const offsetWrap=document.createElement('label');
          offsetWrap.className='lc-mode-hud-control lc-mode-hud-field-group';
          offsetWrap.dataset.modeHudSplashOnly='1';
          const offsetLabel=document.createElement('span');
          offsetLabel.className='lc-mode-hud-control-label';
          offsetLabel.textContent='Offset (in)';
          const offsetInput=document.createElement('input');
          offsetInput.type='number';
          offsetInput.className='lc-input lc-mode-hud-number lc-mode-hud-offset';
          offsetInput.min='0';
          offsetInput.max='1';
          offsetInput.step='.125';
          offsetInput.setAttribute('aria-label','Splash offset in inches');
